import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-002 — Type scale: an 11 px floor, labels at 60 %, upright leads, italic only for quotes and captions","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-002-type-scale-and-the-11px-floor.md","filePath":"uxs/decisions/UXD-002-type-scale-and-the-11px-floor.md"}'),i={name:"uxs/decisions/UXD-002-type-scale-and-the-11px-floor.md"};function r(n,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-002-—-type-scale-an-11-px-floor-labels-at-60-upright-leads-italic-only-for-quotes-and-captions" tabindex="-1">UXD-002 — Type scale: an 11 px floor, labels at 60 %, upright leads, italic only for quotes and captions <a class="header-anchor" href="#uxd-002-—-type-scale-an-11-px-floor-labels-at-60-upright-leads-italic-only-for-quotes-and-captions" aria-label="Permalink to &quot;UXD-002 — Type scale: an 11 px floor, labels at 60 %, upright leads, italic only for quotes and captions&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (proposed and decided)</li><li><strong>Decider</strong>: the operator, as recorded in the plan under &quot;Answers (2026-11-11)&quot; for Q2 (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 430; the plan does not say where the answer was given); slice A1 brief <code>docs/wip/2026-11-11-slice-A1-brief.md</code> lines 6–9</li><li><strong>Answers</strong>: X1, P1, P2, CR1, LI1, G2, G5, Q2; slice A1 (type scale)</li><li><strong>Changes</strong>: <code>src/lib/styles/tokens.css</code> (type scale block); IA §shared-tokens (typography tokens); <code>docs/concept/05_Design_System.md</code> typography and panel rules; AGENTS.md &quot;Design system&quot; type block; UXS-002 to UXS-006, UXS-013, UXS-015 size and italic lines. <em>Rules to be updated to link here (UXS-000 §Next); A1 commits already rewrote most of the text.</em></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Operator list: &quot;some text is too tiny; many panels start with a smaller italic font for no reason&quot; (X1); overview texts &quot;too tiny and italic; they should not be italic or smaller than other texts&quot; (P1); labels &quot;too small and barely readable&quot; (P2). At the A1 baseline (<code>9dda8b6813f</code>) the A1 brief counted 734 literal font sizes below 11 px (414 to change in 121 files), 99 <code>font-style: italic</code> (82 to change) (brief lines 16–20). The plan describes the panel <code>.editorial</code> rules as 11 rules in Crimson italic 13–14 px at 60 % (plan line 327); the brief counts 12 (+4 <code>.empty</code> variants) (brief line 19). The mismatch is not reconciled here. <code>--size-label</code> was 10 px and unused.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>Q2 asked: text floor 10 or 11 px? Lead text in Space Mono upright, as the Gallery does? Keep Crimson italic only for quotes and captions? (plan line 405.)</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The operator&#39;s answer (plan line 430): <strong>floor 11 px everywhere; labels 11 px at about 60 %; body 14 px; lead/overview 15–16 px upright in the body font; italic only for quotes and photo captions, at 14 px or more.</strong></p><p>The numbers the code holds (<code>src/lib/styles/tokens.css</code>, read at <code>9fdf4cc4a6b</code>), which are the binding values:</p><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Role</th></tr></thead><tbody><tr><td><code>--size-label</code></td><td>11 px</td><td>the floor; labels, eyebrows</td></tr><tr><td><code>--color-text-label</code></td><td><code>rgba(255,255,255,0.6)</code></td><td>label colour (60 % white)</td></tr><tr><td><code>--size-meta</code></td><td>12 px</td><td>meta text</td></tr><tr><td><code>--size-body</code></td><td>14 px</td><td>body text</td></tr><tr><td><code>--size-lead</code></td><td>16 px, <strong>15 px at 600 px width and under</strong></td><td>panel overview and page lead, upright Space Mono</td></tr><tr><td><code>--size-caption</code></td><td>14 px</td><td>the only italic (Crimson Pro): real quotes and photo captions</td></tr></tbody></table><p><strong>Where the plan text differs from the tokens.</strong> The plan says lead &quot;15–16 px&quot;. The tokens say 16 px with a phone override of 15 px (<code>@media (max-width: 600px)</code>), so the range is device-dependent, not a free choice. The A1 brief wrote the same (<code>--size-lead: 16px</code> (15px on phones), brief line 13). The slice&#39;s e2e asserts overview text at 15 px or more (brief line 37).</p><p>Also in the slice, from the A1 brief: dev-only tools are exempt; figure and illustration captions keep italic at 14 px or more; inline <code>&lt;em&gt;</code> emphasis in essays is kept; the 2D UI canvases (<code>/plan</code>, <code>SurfaceFlatPatch</code>, <code>surface-2d-map.ts</code>) are UI text and are in scope; 3D sprite labels of the /explore pin scenes are 12 px since slice C2 (<a href="./UXD-020-explore-readability-pins-rings-labels">UXD-020</a>); science charts and Lab canvases keep their own sizes (brief lines 22–28).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Done in slice A1 (commits <code>7661b4242a7</code>, <code>5fa57c98522</code>, <code>16050434512</code>, <code>68e239c3831</code>, <code>3222209b859</code>, plus the test commits <code>aeba55baba1</code> and <code>7c87288441f</code>): tokens, the CSS pass, upright leads, the e2e below, visual baselines regenerated. The slice is in review, not yet signed off by the operator.</li><li>Panel overview text and page leads are upright Space Mono; Crimson Pro italic never carries data or an overview.</li><li>The A1 brief records every allow-list entry, and AGENTS.md carries the canvas allow-list.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>tests/e2e/type-floor.spec.ts</code> crawls every route in <code>scripts/site-routes.mjs</code> plus one open panel per panel type: every visible text node at or above 11 px; label alpha at or above 0.58; overview paragraph upright, Space Mono, at or above 15 px. Canvas and WebGL label textures hold no DOM text and are not covered. Not verified by this document: that the spec passes today.</p>',16)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
